import test from 'node:test';import assert from 'node:assert/strict';
import {normalizeExpeditions,expeditionCell,expeditionRevisit,expeditionTick} from '../src/expeditions.js';import {normalizeTrailMachines,trailMachineAction,trailAllows,trailComplete} from '../src/trail-machines.js';import {normalizeMachines} from '../src/machines.js';
import {normalizeMyWorlds,myWorldAction,myWorldRestore,myWorldCapture,myWorldLeave,beginMyWorldTravel,tickMyWorldTravel,myWorldTravelPose,myWorldView,myWorldJournal,myWorldTileSvg,myWorldRocketSvg} from '../src/my-world.js';
const host=()=>({myWorlds:normalizeMyWorlds(),expeditions:normalizeExpeditions({seed:71,active:'forest'}),trailMachines:normalizeTrailMachines(),machines:normalizeMachines()});
function go(h,id){myWorldAction(h,{type:'create',id});beginMyWorldTravel(h,id);return tickMyWorldTravel(h,0,{skip:true});}
test('three owned destinations keep separate terrain, gardens and creations without changing exploration saves',()=>{const h=host(),before=JSON.stringify(h.expeditions);go(h,'home');h.expeditions.worlds.farm.plots['4,13']={seed:'bean',stage:0,watered:true,harvested:false};h.expeditions.worlds.farm.blocks['5,5']='block';const homeSeed=h.expeditions.seed;go(h,'moon');assert.equal(Object.keys(h.expeditions.worlds.farm.plots).length,0);assert.notEqual(h.expeditions.seed,homeSeed);go(h,'home');assert.equal(h.expeditions.worlds.farm.plots['4,13'].stage,1);assert.equal(h.expeditions.worlds.farm.blocks['5,5'],'block');myWorldLeave(h);assert.equal(JSON.stringify(h.expeditions),before);});
test('reload restores an active colony without advancing crop stages, and only a return visit advances one stage',()=>{const h=host();go(h,'planet');h.expeditions.worlds.farm.plots['2,2']={seed:'bean',stage:1,watered:true,harvested:false};myWorldCapture(h);const reloaded={...host(),myWorlds:normalizeMyWorlds(JSON.parse(JSON.stringify(h.myWorlds)))};myWorldRestore(reloaded);assert.equal(reloaded.expeditions.worlds.farm.plots['2,2'].stage,1);assert.equal(reloaded.expeditions.colony.kind,'planet');beginMyWorldTravel(reloaded,'planet');tickMyWorldTravel(reloaded,0,{skip:true});assert.equal(reloaded.expeditions.worlds.farm.plots['2,2'].stage,1);beginMyWorldTravel(reloaded,'hub');tickMyWorldTravel(reloaded,0,{skip:true});go(reloaded,'planet');assert.equal(reloaded.expeditions.worlds.farm.plots['2,2'].stage,2);});
test('off-world travel includes rocket transformation, launch, spaceflight, landing and unfolding without timed input',()=>{const h=host();myWorldAction(h,{type:'create',id:'moon'});beginMyWorldTravel(h,'moon',{x:300,y:400});const stages=new Set();let arrived=null;for(let i=0;i<400&&!arrived;i++){stages.add(myWorldTravelPose(h.myWorlds).stage);arrived=tickMyWorldTravel(h,.05);}assert.deepEqual([...stages],['depart','form','launch','space','land','unfold']);assert.equal(arrived.arrived,'moon');assert.equal(h.myWorlds.worlds.moon.visits,1);assert.equal(h.myWorlds.travel,null);});
test('travel can pause, be canceled, resume after reload or be skipped with reduced sensory settings',()=>{const h=host();myWorldAction(h,{type:'create',id:'planet'});beginMyWorldTravel(h,'planet');tickMyWorldTravel(h,.05);const saved=JSON.stringify(h.myWorlds.travel);tickMyWorldTravel(h,.05,{paused:true});tickMyWorldTravel(h,.05,{overlay:true});assert.equal(JSON.stringify(h.myWorlds.travel),saved);h.myWorlds=normalizeMyWorlds(JSON.parse(JSON.stringify(h.myWorlds)));assert.equal(h.myWorlds.travel.time,.05);h.myWorlds.travel=null;assert.equal(h.myWorlds.active,null);assert.equal(h.myWorlds.worlds.planet.visits,0);beginMyWorldTravel(h,'planet');assert.equal(tickMyWorldTravel(h,0,{reduced:true}).arrived,'planet');beginMyWorldTravel(h,'hub');assert.equal(tickMyWorldTravel(h,0,{effects:false}).hub,true);});
test('naming and landscape setup are optional and non-destructive after progress exists',()=>{const h=host();myWorldAction(h,{type:'name',id:'home',value:'<Nova>\n'});assert.equal(h.myWorlds.worlds.home.name,'Nova');myWorldAction(h,{type:'landscape',id:'home',value:'lake'});go(h,'home');myWorldAction(h,{type:'landscape',id:'home',value:'rocky'});assert.equal(h.myWorlds.worlds.home.landscape,'lake');for(let i=0;i<40;i++)myWorldAction(h,{type:'key',id:'moon',value:'A'});assert.equal(h.myWorlds.worlds.moon.name.length,24);assert.ok(myWorldJournal(h.myWorlds,'adventures').some(e=>e.myWorldId==='home'));});
test('colony bridges and machines use their own saved placement context; exploration farm compatibility is retained',()=>{const h=host();go(h,'planet');const garage=normalizeMachines({models:[{id:'m1',type:'bridge',color:'purple'}]});assert.equal(trailAllows(garage.models[0],'farm'),false);const r=trailMachineAction(h.expeditions,h.trailMachines,garage,{type:'place',modelId:'m1',pad:0});assert.ok(r.enter);assert.equal(h.trailMachines.placements[0].mode,'farm');myWorldCapture(h);const saved=normalizeMyWorlds(h.myWorlds);assert.equal(saved.worlds.planet.trailMachines.placements.length,1);go(h,'moon');assert.equal(h.trailMachines.placements.length,0);});
test('all setup menus fit native button limits and both celestial views use original graphics',()=>{const s=normalizeMyWorlds();for(const id of ['home','planet','moon'])for(const route of ['home','world:'+id,'name:'+id,'letters:'+id+':0','letters:'+id+':8','landscape:'+id,'help'])assert.ok(myWorldView(s,route).actions.length<=6,route);assert.match(myWorldRocketSvg(),/#35d3c9/);assert.match(myWorldTileSvg('moon','grass'),/#aeb0bb/);assert.equal(normalizeMyWorlds({active:'bad',travel:{to:'bad'}}).travel,null);});

test('a colony bridge carries the astronaut across a prepared water channel and can be packed without terrain loss',()=>{const h=host();go(h,'planet');const garage=normalizeMachines({models:[{id:'m1',type:'bridge',color:'purple'}]});const placed=trailMachineAction(h.expeditions,h.trailMachines,garage,{type:'place',modelId:'m1',pad:0}),p=h.trailMachines.placements[0];expeditionRevisit(h.expeditions,'farm',placed.effect.focus);const w=h.expeditions.worlds.farm,start=w.x;assert.equal(expeditionCell(w,'farm',p.x/40,p.y/40-1).solid,true);trailMachineAction(h.expeditions,h.trailMachines,garage,{type:'use',id:p.id});for(let i=0;i<150;i++){const r=expeditionTick(h.expeditions,.05);if(r.arrived?.kind==='trailCross')trailComplete(h.trailMachines,r.arrived.id,'cross');}assert.ok(w.x-start>150);assert.ok(h.trailMachines.history.some(e=>e.kind==='cross'));trailMachineAction(h.expeditions,h.trailMachines,garage,{type:'pack',id:p.id});assert.equal(Object.keys(w.deploymentCells).length,0);});
